BULLES_LOAD({"ep":"maupassant/03","part":"text","paras":[{"poem":false,"s":[{"fr":"Un vieux pauvre, à barbe blanche, nous demanda l’aumône.","en":"A poor old man with a white beard asked us for money.","pt":"Um velho pobre, de barba branca, pediu-nos esmola.","es":"Un viejo pobre, de barba blanca, nos pidió limosna."},{"fr":"Mon camarade Joseph Davranche lui donna cent sous.","en":"My friend Joseph Davranche gave him five francs.","pt":"O meu amigo Joseph Davranche deu-lhe cinco francos.","es":"Mi compañero Joseph Davranche le dio cinco francos."},{"fr":"Je fus surpris.","en":"I was surprised.","pt":"Fiquei surpreendido.","es":"Me sorprendió."},{"fr":"Il me dit :","en":"He said to me:","pt":"Ele disse-me:","es":"Me dijo:"}]},{"poem":false,"s":[{"fr":"— Ce misérable m’a rappelé une histoire que je vais te dire et dont le souvenir me poursuit sans cesse.","en":"\"That poor wretch reminded me of a story I'm going to tell you, one whose memory haunts me constantly.","pt":"— Aquele desgraçado fez-me lembrar uma história que te vou contar e cuja recordação me persegue sem parar.","es":"—Este desgraciado me ha recordado una historia que te voy a contar y cuyo recuerdo me persigue sin cesar."},{"fr":"La voici :","en":"Here it is:","pt":"É esta:","es":"Aquí está:"}]},{"poem":false,"s":[{"fr":"Ma famille, originaire du Havre, n’était pas riche.","en":"My family, who came from Le Havre, wasn't rich.","pt":"A minha família, natural do Havre, não era rica.","es":"Mi familia, que era de El Havre, no era rica."},{"fr":"On s’en tirait, voilà tout.","en":"We got by, that's all.","pt":"Lá nos íamos governando, e mais nada.","es":"Íbamos tirando, y nada más."},{"fr":"Le père travaillait, rentrait tard du bureau et ne gagnait pas grand-chose.","en":"My father worked, came home late from the office and didn't earn much.","pt":"O meu pai trabalhava, chegava tarde do escritório e não ganhava grande coisa.","es":"Mi padre trabajaba, volvía tarde de la oficina y no ganaba gran cosa."},{"fr":"J’avais deux sœurs.","en":"I had two sisters.","pt":"Eu tinha duas irmãs.","es":"Yo tenía dos hermanas."}]},{"poem":false,"s":[{"fr":"Ma mère souffrait beaucoup de la gêne où nous vivions, et elle trouvait souvent des paroles aigres pour son mari, des reproches voilés et perfides.","en":"My mother suffered a great deal from the hard times we lived in, and she often had bitter words for her husband, veiled and spiteful reproaches.","pt":"A minha mãe sofria muito com as dificuldades em que vivíamos, e tinha muitas vezes palavras azedas para o marido, censuras veladas e pérfidas.","es":"Mi madre sufría mucho por las estrecheces en que vivíamos, y a menudo encontraba palabras agrias para su marido, reproches velados y pérfidos."},{"fr":"Le pauvre homme avait alors un geste qui me navrait.","en":"Then the poor man would make a gesture that broke my heart.","pt":"O pobre homem fazia então um gesto que me cortava o coração.","es":"El pobre hombre hacía entonces un gesto que me partía el alma."},{"fr":"Il se passait la main ouverte sur le front, comme pour essuyer une sueur qui n’existait pas, et il ne répondait rien.","en":"He would pass his open hand across his forehead, as if to wipe away sweat that wasn't there, and say nothing.","pt":"Passava a mão aberta pela testa, como para limpar um suor que não existia, e não respondia nada.","es":"Se pasaba la mano abierta por la frente, como para secarse un sudor que no existía, y no respondía nada."},{"fr":"Je sentais sa douleur impuissante.","en":"I could feel his helpless pain.","pt":"Eu sentia a sua dor impotente.","es":"Yo sentía su dolor impotente."},{"fr":"On économisait sur tout ; on n’acceptait jamais un dîner, pour n’avoir pas à le rendre ; on achetait les provisions au rabais, les fonds de boutique.","en":"We saved on everything; we never accepted a dinner invitation, so as not to have to return it; we bought our food cut-price, the leftovers at the bottom of the shop.","pt":"Poupava-se em tudo; nunca se aceitava um jantar, para não ter de o retribuir; compravam-se as provisões em saldo, os restos das lojas.","es":"Se ahorraba en todo; nunca se aceptaba una invitación a cenar, para no tener que devolverla; se compraban las provisiones de saldo, los restos de las tiendas."},{"fr":"Mes sœurs faisaient leurs robes elles-mêmes et avaient de longues discussions sur le prix du galon qui valait quinze centimes le mètre.","en":"My sisters made their own dresses and had long arguments about the price of braid at fifteen centimes a metre.","pt":"As minhas irmãs faziam elas próprias os vestidos e tinham longas discussões sobre o preço do galão, que custava quinze cêntimos o metro.","es":"Mis hermanas se hacían ellas mismas los vestidos y tenían largas discusiones sobre el precio del galón, que costaba quince céntimos el metro."},{"fr":"Notre nourriture ordinaire consistait en soupe grasse et bœuf accommodé à toutes les sauces.","en":"Our usual food was meat broth and beef served with every kind of sauce.","pt":"A nossa comida habitual era sopa de carne e vaca preparada com todos os molhos.","es":"Nuestra comida habitual consistía en caldo y carne de vaca guisada con todas las salsas posibles."},{"fr":"Cela est sain et réconfortant, parait-il ; j’aurais préféré autre chose.","en":"That's healthy and nourishing, they say; I would have preferred something else.","pt":"Ao que parece, é saudável e reconfortante; eu teria preferido outra coisa.","es":"Al parecer, es sano y reconfortante; yo habría preferido otra cosa."}]},{"poem":false,"s":[{"fr":"On me faisait des scènes abominables pour les boutons perdus et les pantalons déchirés.","en":"I got dreadful scoldings for lost buttons and torn trousers.","pt":"Faziam-me cenas horríveis por causa dos botões perdidos e das calças rasgadas.","es":"Me montaban escenas espantosas por los botones perdidos y los pantalones rotos."}]},{"poem":false,"s":[{"fr":"Mais chaque dimanche nous allions faire notre tour de jetée en grande tenue.","en":"But every Sunday we went for our walk along the pier in our best clothes.","pt":"Mas todos os domingos íamos dar a nossa volta ao paredão, vestidos a rigor.","es":"Pero cada domingo íbamos a dar nuestra vuelta por el malecón con nuestras mejores galas."},{"fr":"Mon père, en redingote, en grand chapeau, en gants, offrait le bras à ma mère, pavoisée comme un navire un jour de fête.","en":"My father, in his frock coat, top hat and gloves, offered his arm to my mother, who was decked out like a ship on a holiday.","pt":"O meu pai, de sobrecasaca, chapéu alto e luvas, dava o braço à minha mãe, embandeirada como um navio em dia de festa.","es":"Mi padre, con levita, sombrero de copa y guantes, ofrecía el brazo a mi madre, engalanada como un barco en día de fiesta."},{"fr":"Mes sœurs, prêtes les premières, attendaient le signal du départ ; mais, au dernier moment, on découvrait toujours une tache oubliée sur la redingote du père de famille, et il fallait bien vite l’effacer avec un chiffon mouillé de benzine.","en":"My sisters, who were ready first, waited for the signal to leave; but at the last moment someone always found a forgotten stain on the head of the family's frock coat, and it had to be rubbed off quickly with a rag dipped in benzine.","pt":"As minhas irmãs, as primeiras a ficar prontas, esperavam o sinal de partida; mas, no último momento, descobria-se sempre uma nódoa esquecida na sobrecasaca do pai de família, e era preciso tirá-la depressa com um trapo molhado em benzina.","es":"Mis hermanas, listas las primeras, esperaban la señal de salida; pero en el último momento siempre se descubría una mancha olvidada en la levita del padre de familia, y había que quitarla deprisa con un trapo mojado en bencina."}]},{"poem":false,"s":[{"fr":"Mon père, gardant son grand chapeau sur la tête, attendait, en manches de chemise, que l’opération fût terminée, tandis que ma mère se hâtait, ayant ajusté ses lunettes de myope, et ôté ses gants pour ne les pas gâter.","en":"My father, keeping his top hat on his head, waited in his shirtsleeves for the operation to be finished, while my mother hurried, having put on her short-sighted spectacles and taken off her gloves so as not to spoil them.","pt":"O meu pai, sem tirar o chapéu alto da cabeça, esperava em mangas de camisa que a operação acabasse, enquanto a minha mãe se apressava, depois de ajeitar os óculos de míope e tirar as luvas para não as estragar.","es":"Mi padre, sin quitarse el sombrero de copa, esperaba en mangas de camisa a que terminara la operación, mientras mi madre se daba prisa, con sus gafas de miope bien puestas y los guantes quitados para no estropearlos."}]},{"poem":false,"s":[{"fr":"On se mettait en route avec cérémonie.","en":"We set off with great ceremony.","pt":"Púnhamo-nos a caminho com cerimónia.","es":"Nos poníamos en camino con ceremonia."},{"fr":"Mes sœurs marchaient devant, en se donnant le bras.","en":"My sisters walked in front, arm in arm.","pt":"As minhas irmãs iam à frente, de braço dado.","es":"Mis hermanas iban delante, cogidas del brazo."},{"fr":"Elles étaient en âge de mariage, et on en faisait montre en ville.","en":"They were of marrying age, and they were being shown off in town.","pt":"Estavam em idade de casar, e eram exibidas pela cidade.","es":"Estaban en edad de casarse, y se las exhibía por la ciudad."},{"fr":"Je me tenais à gauche de ma mère, dont mon père gardait la droite.","en":"I walked on my mother's left, and my father on her right.","pt":"Eu ia à esquerda da minha mãe, e o meu pai à direita.","es":"Yo iba a la izquierda de mi madre, y mi padre a su derecha."},{"fr":"Et je me rappelle l’air pompeux de mes pauvres parents dans ces promenades du dimanche, la rigidité de leurs traits, la sévérité de leur allure.","en":"And I remember my poor parents' pompous air on those Sunday walks, their stiff faces and their stern bearing.","pt":"E lembro-me do ar pomposo dos meus pobres pais naqueles passeios de domingo, da rigidez das suas feições, da severidade do seu porte.","es":"Y recuerdo el aire pomposo de mis pobres padres en aquellos paseos del domingo, la rigidez de sus rasgos, la severidad de su porte."},{"fr":"Ils avançaient d’un pas grave, le corps droit, les jambes raides, comme si une affaire d’une importance extrême eût dépendu de leur tenue.","en":"They moved with a solemn step, bodies upright and legs stiff, as if some matter of the greatest importance depended on how they carried themselves.","pt":"Avançavam com passo grave, o corpo direito, as pernas hirtas, como se um assunto da maior importância dependesse da sua compostura.","es":"Avanzaban con paso grave, el cuerpo derecho y las piernas rígidas, como si de su compostura dependiera un asunto de extrema importancia."}]},{"poem":false,"s":[{"fr":"Et chaque dimanche, en voyant entrer les grands navires qui revenaient de pays inconnus et lointains, mon père prononçait invariablement les mêmes paroles :","en":"And every Sunday, seeing the big ships coming in from distant, unknown countries, my father would say the very same words without fail:","pt":"E todos os domingos, ao ver entrar os grandes navios que voltavam de países desconhecidos e distantes, o meu pai dizia invariavelmente as mesmas palavras:","es":"Y cada domingo, al ver entrar los grandes barcos que volvían de países desconocidos y lejanos, mi padre pronunciaba invariablemente las mismas palabras:"}]},{"poem":false,"s":[{"fr":"— Hein ! si Jules était là-dedans, quelle surprise !","en":"'Eh! What a surprise if Jules were on that one!'","pt":"«Hem! Se o Jules viesse ali dentro, que surpresa!»","es":"—¡Eh! ¡Si Jules viniera ahí dentro, qué sorpresa!"}]},{"poem":false,"s":[{"fr":"Mon oncle Jules, le frère de mon père, était le seul espoir de la famille, après en avoir été la terreur.","en":"My uncle Jules, my father's brother, was the family's only hope, after having been its terror.","pt":"O meu tio Jules, irmão do meu pai, era a única esperança da família, depois de ter sido o seu terror.","es":"Mi tío Jules, el hermano de mi padre, era la única esperanza de la familia, después de haber sido su terror."},{"fr":"J’avais entendu parler de lui depuis mon enfance, et il me semblait que je l’aurais reconnu du premier coup, tant sa pensée m’était devenue familière.","en":"I had heard about him since I was a child, and I felt I would have recognised him at once, the thought of him had become so familiar to me.","pt":"Ouvia falar dele desde pequeno, e parecia-me que o reconheceria à primeira, tão familiar se me tinha tornado a ideia dele.","es":"Había oído hablar de él desde mi infancia, y me parecía que lo habría reconocido a la primera, de tan familiar como se me había vuelto su recuerdo."},{"fr":"Je savais tous les détails de son existence jusqu’au jour de son départ pour l’Amérique, bien qu’on ne parlât qu’à voix basse de cette période de sa vie.","en":"I knew every detail of his life up to the day he left for America, even though that period of his life was only spoken of in whispers.","pt":"Sabia todos os pormenores da sua vida até ao dia em que partira para a América, embora só se falasse em voz baixa desse período da sua vida.","es":"Conocía todos los detalles de su vida hasta el día en que se marchó a América, aunque de aquella época de su vida solo se hablaba en voz baja."}]},{"poem":false,"s":[{"fr":"Il avait eu, parait-il, une mauvaise conduite, c’est-à-dire qu’il avait mangé quelque argent, ce qui est bien le plus grand des crimes pour les familles pauvres.","en":"He had, it seems, behaved badly, which is to say he had squandered some money, which is the greatest of crimes for poor families.","pt":"Ao que parece, tinha-se portado mal, quer dizer, tinha esbanjado algum dinheiro, o que é o maior de todos os crimes para as famílias pobres.","es":"Al parecer se había portado mal, es decir, se había gastado algo de dinero, lo cual es el mayor de los crímenes para las familias pobres."},{"fr":"Chez les riches, un homme qui s’amuse fait des bêtises.","en":"Among the rich, a man who enjoys himself is just being foolish.","pt":"Entre os ricos, um homem que se diverte faz asneiras.","es":"Entre los ricos, un hombre que se divierte hace tonterías."},{"fr":"Il est ce qu’on appelle en souriant, un noceur.","en":"He's what people call, with a smile, a playboy.","pt":"É aquilo a que se chama, a sorrir, um estroina.","es":"Es lo que se llama, sonriendo, un juerguista."},{"fr":"Chez les nécessiteux, un garçon qui force les parents à écorner le capital devient un mauvais sujet, un gueux, un drôle !","en":"Among the needy, a boy who forces his parents to dip into their savings becomes a bad lot, a good-for-nothing, a scoundrel!","pt":"Entre os necessitados, um rapaz que obriga os pais a mexer no capital torna-se um mau sujeito, um pelintra, um patife!","es":"Entre los necesitados, un muchacho que obliga a sus padres a tocar el capital se convierte en un mal sujeto, un pillo, ¡un sinvergüenza!"}]},{"poem":false,"s":[{"fr":"Et cette distinction est juste, bien que le fait soit le même, car les conséquences seules déterminent la gravité de l’acte.","en":"And that distinction is fair, even though the deed is the same, because only the consequences decide how serious an act is.","pt":"E esta distinção é justa, embora o ato seja o mesmo, porque só as consequências determinam a gravidade do ato.","es":"Y esa distinción es justa, aunque el hecho sea el mismo, porque solo las consecuencias determinan la gravedad del acto."}]},{"poem":false,"s":[{"fr":"Enfin l’oncle Jules avait notablement diminué l’héritage sur lequel comptait mon père ; après avoir d’ailleurs mangé sa part jusqu’au dernier sou.","en":"In short, Uncle Jules had considerably reduced the inheritance my father was counting on, after spending his own share down to the last penny.","pt":"Em suma, o tio Jules tinha reduzido bastante a herança com que o meu pai contava, depois, aliás, de ter esbanjado a sua parte até ao último tostão.","es":"En fin, el tío Jules había mermado notablemente la herencia con la que contaba mi padre, después de haberse gastado, por lo demás, su parte hasta el último céntimo."}]},{"poem":false,"s":[{"fr":"On l’avait embarqué pour l’Amérique, comme on faisait alors, sur un navire marchand allant du Havre à New-York.","en":"He had been shipped off to America, as people did in those days, on a merchant ship going from Le Havre to New York.","pt":"Tinham-no embarcado para a América, como então se fazia, num navio mercante que ia do Havre para Nova Iorque.","es":"Lo habían embarcado para América, como se hacía entonces, en un barco mercante que iba de El Havre a Nueva York."}]},{"poem":false,"s":[{"fr":"Une fois là-bas, mon oncle Jules s’établit marchand de je ne sais quoi, et il écrivit qu’il gagnait un peu d’argent et qu’il espérait pouvoir dédommager mon père du tort qu’il lui avait fait.","en":"Once over there, my uncle Jules set himself up as a dealer in I don't know what, and he wrote that he was earning a little money and hoped to be able to make up to my father for the harm he had done him.","pt":"Uma vez lá, o meu tio Jules estabeleceu-se como negociante de não sei quê, e escreveu a dizer que ganhava algum dinheiro e que esperava poder compensar o meu pai do mal que lhe tinha feito.","es":"Una vez allí, mi tío Jules se estableció como comerciante de no sé qué, y escribió diciendo que ganaba un poco de dinero y que esperaba poder resarcir a mi padre del daño que le había hecho."},{"fr":"Cette lettre causa dans la famille une émotion profonde.","en":"That letter caused a great stir in the family.","pt":"Esta carta causou na família uma comoção profunda.","es":"Aquella carta causó en la familia una emoción profunda."},{"fr":"Jules, qui ne valait pas, comme on dit, les quatre fers d’un chien, devint tout à coup un honnête homme, un garçon de cœur, un vrai Davranche, intègre comme tous les Davranche.","en":"Jules, who as the saying goes wasn't worth a brass farthing, suddenly became an honest man, a good-hearted fellow, a true Davranche, as upright as all the Davranches.","pt":"O Jules, que, como se costuma dizer, não valia um caracol, tornou-se de repente um homem honesto, um rapaz de bom coração, um verdadeiro Davranche, íntegro como todos os Davranche.","es":"Jules, que no valía, como suele decirse, ni un pimiento, se convirtió de repente en un hombre honrado, un muchacho de buen corazón, un verdadero Davranche, íntegro como todos los Davranche."}]},{"poem":false,"s":[{"fr":"Un capitaine nous apprit en outre qu’il avait loué une grande boutique et qu’il faisait un commerce important.","en":"What's more, a ship's captain told us he had rented a big shop and was doing a lot of business.","pt":"Além disso, um capitão contou-nos que ele tinha alugado uma grande loja e que fazia um negócio importante.","es":"Un capitán nos contó, además, que había alquilado una tienda grande y que tenía un comercio importante."}]},{"poem":false,"s":[{"fr":"Une seconde lettre, deux ans plus tard, disait : « Mon cher Philippe, je t’écris pour que tu ne t’inquiètes pas de ma santé, qui est bonne.","en":"A second letter, two years later, said: 'My dear Philippe, I am writing so that you will not worry about my health, which is good.","pt":"Uma segunda carta, dois anos depois, dizia: «Meu caro Philippe, escrevo-te para não te preocupares com a minha saúde, que é boa.","es":"Una segunda carta, dos años después, decía: «Mi querido Philippe: te escribo para que no te preocupes por mi salud, que es buena."},{"fr":"Les affaires aussi vont bien.","en":"Business is going well too.","pt":"Os negócios também vão bem.","es":"Los negocios también van bien."},{"fr":"Je pars demain pour un long voyage dans l’Amérique du Sud.","en":"I am leaving tomorrow on a long journey to South America.","pt":"Parto amanhã para uma longa viagem pela América do Sul.","es":"Mañana salgo para un largo viaje por América del Sur."},{"fr":"Je serai peut-être plusieurs années sans te donner de mes nouvelles.","en":"I may go several years without sending you news.","pt":"Talvez passe vários anos sem te dar notícias.","es":"Puede que pase varios años sin darte noticias."},{"fr":"Si je ne t’écris pas, ne sois pas inquiet.","en":"If I don't write, don't worry.","pt":"Se não te escrever, não fiques preocupado.","es":"Si no te escribo, no te preocupes."},{"fr":"Je reviendrai au Havre une fois fortune faite.","en":"I will come back to Le Havre once I have made my fortune.","pt":"Voltarei ao Havre quando tiver feito fortuna.","es":"Volveré a El Havre cuando haya hecho fortuna."},{"fr":"J’espère que ce ne sera pas trop long, et nous vivrons heureux ensemble… »","en":"I hope it won't be too long, and we will live happily together…'","pt":"Espero que não demore muito, e viveremos felizes juntos…»","es":"Espero que no tarde demasiado, y viviremos felices juntos…»."}]},{"poem":false,"s":[{"fr":"Cette lettre était devenue l’évangile de la famille.","en":"That letter had become the family gospel.","pt":"Esta carta tinha-se tornado o evangelho da família.","es":"Aquella carta se había convertido en el evangelio de la familia."},{"fr":"On la lisait à tout propos, on la montrait à tout le monde.","en":"It was read at every opportunity and shown to everyone.","pt":"Lia-se a propósito de tudo, mostrava-se a toda a gente.","es":"Se leía a la menor ocasión, se le enseñaba a todo el mundo."}]},{"poem":false,"s":[{"fr":"Pendant dix ans en effet, l’oncle Jules ne donna plus de nouvelles ; mais l’espoir de mon père grandissait à mesure que le temps marchait ; et ma mère disait souvent :","en":"And indeed, for ten years Uncle Jules sent no more news; but my father's hope grew as time went by, and my mother would often say:","pt":"De facto, durante dez anos, o tio Jules não deu mais notícias; mas a esperança do meu pai crescia à medida que o tempo passava; e a minha mãe dizia muitas vezes:","es":"Durante diez años, en efecto, el tío Jules no volvió a dar noticias; pero la esperanza de mi padre crecía a medida que pasaba el tiempo; y mi madre decía a menudo:"}]},{"poem":false,"s":[{"fr":"— Quand ce bon Jules sera là, notre situation changera.","en":"'When our good Jules is here, things will change for us.","pt":"«Quando o bom do Jules cá estiver, a nossa situação vai mudar.","es":"—Cuando el bueno de Jules esté aquí, nuestra situación cambiará."},{"fr":"En voilà un qui a su se tirer d’affaire !","en":"There's a man who knew how to get on in the world!'","pt":"Aí está um que se soube desenrascar!»","es":"¡Ese sí que ha sabido salir adelante!"}]},{"poem":false,"s":[{"fr":"Et chaque dimanche, en regardant venir de l’horizon les gros vapeurs noirs vomissant sur le ciel des serpents de fumée, mon père répétait sa phrase éternelle :","en":"And every Sunday, watching the big black steamers coming over the horizon, spewing serpents of smoke into the sky, my father repeated his eternal phrase:","pt":"E todos os domingos, ao ver chegar do horizonte os grandes vapores negros que vomitavam no céu serpentes de fumo, o meu pai repetia a sua frase eterna:","es":"Y cada domingo, al ver venir del horizonte los grandes vapores negros que vomitaban sobre el cielo serpientes de humo, mi padre repetía su frase eterna:"}]},{"poem":false,"s":[{"fr":"— Hein ! si Jules était là-dedans, quelle surprise !","en":"'Eh! What a surprise if Jules were on that one!'","pt":"«Hem! Se o Jules viesse ali dentro, que surpresa!»","es":"—¡Eh! ¡Si Jules viniera ahí dentro, qué sorpresa!"}]},{"poem":false,"s":[{"fr":"Et on s’attendait presque à le voir agiter un mouchoir, et crier :","en":"And we almost expected to see him waving a handkerchief and shouting:","pt":"E quase se esperava vê-lo agitar um lenço e gritar:","es":"Y casi esperábamos verlo agitar un pañuelo y gritar:"}]},{"poem":false,"s":[{"fr":"— Ohé !","en":"'Hey there!","pt":"«Olá!","es":"—¡Eh!"},{"fr":"Philippe.","en":"Philippe!'","pt":"Philippe!»","es":"¡Philippe!"}]},{"poem":false,"s":[{"fr":"On avait échafaudé mille projets sur ce retour assuré ; on devait même acheter, avec l’argent de l’oncle, une petite maison de campagne près d’Ingouville.","en":"We had built a thousand plans on this certain return; with Uncle's money we were even going to buy a little country house near Ingouville.","pt":"Tinham-se arquitetado mil projetos sobre aquele regresso garantido; com o dinheiro do tio, devia até comprar-se uma casinha de campo perto de Ingouville.","es":"Se habían levantado mil proyectos sobre aquel regreso seguro; con el dinero del tío incluso íbamos a comprar una casita de campo cerca de Ingouville."},{"fr":"Je n’affirmerais pas que mon père n’eût point entamé déjà des négociations à ce sujet.","en":"I wouldn't swear that my father hadn't already started negotiations about it.","pt":"Não juraria que o meu pai não tivesse já começado negociações nesse sentido.","es":"No afirmaría yo que mi padre no hubiera empezado ya negociaciones al respecto."}]},{"poem":false,"s":[{"fr":"L’aînée de mes sœurs avait alors vingt-huit ans ; l’autre vingt-six.","en":"My elder sister was twenty-eight by then, the other twenty-six.","pt":"A mais velha das minhas irmãs tinha então vinte e oito anos; a outra vinte e seis.","es":"La mayor de mis hermanas tenía entonces veintiocho años; la otra, veintiséis."},{"fr":"Elles ne se mariaient pas, et c’était là un gros chagrin pour tout le monde.","en":"They weren't getting married, and that was a great sorrow for everyone.","pt":"Não se casavam, e isso era um grande desgosto para todos.","es":"No se casaban, y eso era una gran pena para todos."}]},{"poem":false,"s":[{"fr":"Un prétendant enfin se présenta pour la seconde.","en":"At last a suitor came forward for the younger one.","pt":"Por fim, apareceu um pretendente para a segunda.","es":"Por fin se presentó un pretendiente para la segunda."},{"fr":"Un employé, pas riche, mais honorable.","en":"A clerk, not rich, but respectable.","pt":"Um empregado, não rico, mas honrado.","es":"Un empleado, no rico, pero honrado."},{"fr":"J’ai toujours eu la conviction que la lettre de l’oncle Jules, montrée un soir, avait terminé les hésitations et emporté la résolution du jeune homme.","en":"I've always been convinced that Uncle Jules's letter, shown to him one evening, put an end to the young man's hesitations and made up his mind.","pt":"Sempre tive a convicção de que a carta do tio Jules, mostrada numa noite, tinha acabado com as hesitações do rapaz e decidido a sua resolução.","es":"Siempre he estado convencido de que la carta del tío Jules, que se le enseñó una noche, acabó con las vacilaciones del joven y lo decidió."}]},{"poem":false,"s":[{"fr":"On l’accepta avec empressement, et il fut décidé qu’après le mariage toute la famille ferait ensemble un petit voyage à Jersey.","en":"He was accepted eagerly, and it was decided that after the wedding the whole family would take a little trip to Jersey together.","pt":"Aceitaram-no com entusiasmo, e ficou decidido que, depois do casamento, a família toda faria junta uma pequena viagem a Jersey.","es":"Se le aceptó con entusiasmo, y se decidió que, después de la boda, toda la familia haría junta un pequeño viaje a Jersey."}]},{"poem":false,"s":[{"fr":"Jersey est l’idéal du voyage pour les gens pauvres.","en":"Jersey is the ideal trip for poor people.","pt":"Jersey é a viagem ideal para os pobres.","es":"Jersey es el viaje ideal para la gente pobre."},{"fr":"Ce n’est pas loin ; on passe la mer dans un paquebot et on est en terre étrangère, cet îlot appartenant aux Anglais.","en":"It isn't far; you cross the sea on a steamer and you're in a foreign land, since this little island belongs to the English.","pt":"Não é longe; atravessa-se o mar num paquete e está-se em terra estrangeira, porque esta ilhota pertence aos ingleses.","es":"No está lejos; se cruza el mar en un vapor y se está en tierra extranjera, porque ese islote pertenece a los ingleses."},{"fr":"Donc, un Français, avec deux heures de navigation, peut s’offrir la vue d’un peuple voisin chez lui et étudier les mœurs, déplorables d’ailleurs, de cette île couverte par le pavillon britannique, comme disent les gens qui parlent avec simplicité.","en":"So a Frenchman, with two hours at sea, can treat himself to the sight of a neighbouring people in their own home and study the customs, deplorable as they are, of this island under the British flag, as people who speak plainly put it.","pt":"Assim, um francês, com duas horas de navegação, pode dar-se ao luxo de ver um povo vizinho em sua casa e estudar os costumes, aliás deploráveis, desta ilha coberta pela bandeira britânica, como diz quem fala com simplicidade.","es":"Así que un francés, con dos horas de navegación, puede permitirse ver a un pueblo vecino en su casa y estudiar las costumbres, deplorables por lo demás, de esa isla cubierta por el pabellón británico, como dice la gente que habla con sencillez."}]},{"poem":false,"s":[{"fr":"Ce voyage de Jersey devint notre préoccupation, notre unique attente, notre rêve de tous les instants.","en":"That trip to Jersey became our main concern, the one thing we looked forward to, our dream every moment.","pt":"Aquela viagem a Jersey tornou-se a nossa preocupação, a nossa única expectativa, o nosso sonho de todos os instantes.","es":"Aquel viaje a Jersey se convirtió en nuestra preocupación, nuestra única ilusión, nuestro sueño de cada instante."}]},{"poem":false,"s":[{"fr":"On partit enfin.","en":"At last we set off.","pt":"Partimos finalmente.","es":"Por fin salimos."},{"fr":"Je vois cela comme si c’était d’hier : le vapeur chauffant contre le quai de Granville ;","en":"I can see it as if it were yesterday: the steamer getting up steam at the quay in Granville;","pt":"Vejo aquilo como se fosse ontem: o vapor a aquecer junto ao cais de Granville;","es":"Lo veo como si fuera ayer: el vapor echando humo junto al muelle de Granville;"},{"fr":"mon père, effaré, surveillant l’embarquement de nos trois colis ; ma mère inquiète ayant pris le bras de ma sœur non mariée, qui semblait perdue depuis le départ de l’autre, comme un poulet resté seul de sa couvée ;","en":"my father, flustered, watching our three bags being loaded; my mother anxious, holding the arm of my unmarried sister, who seemed lost since the other one had gone, like a chick left alone from its brood;","pt":"o meu pai, atarantado, a vigiar o embarque das nossas três malas; a minha mãe, inquieta, de braço dado com a minha irmã solteira, que parecia perdida desde a partida da outra, como um pinto que ficou sozinho da ninhada;","es":"mi padre, nervioso, vigilando el embarque de nuestros tres bultos; mi madre, inquieta, cogida del brazo de mi hermana soltera, que parecía perdida desde la marcha de la otra, como un pollito que se ha quedado solo de su nidada;"},{"fr":"et, derrière nous, les nouveaux époux qui restaient toujours en arrière, ce qui me faisait souvent tourner la tête.","en":"and behind us the newlyweds, who always lagged behind, which often made me turn my head.","pt":"e, atrás de nós, os recém-casados, que ficavam sempre para trás, o que me fazia muitas vezes virar a cabeça.","es":"y, detrás de nosotros, los recién casados, que se quedaban siempre atrás, lo que me hacía volver la cabeza a menudo."}]},{"poem":false,"s":[{"fr":"Le bâtiment siffla.","en":"The ship whistled.","pt":"O barco apitou.","es":"El barco silbó."},{"fr":"Nous voici montés, et le navire, quittant la jetée, s’éloigna sur une mer plate comme une table de marbre vert.","en":"Here we are on board, and the ship, leaving the pier, moved off over a sea as flat as a green marble table.","pt":"Ei-nos a bordo, e o navio, deixando o paredão, afastou-se sobre um mar liso como uma mesa de mármore verde.","es":"Ya estamos a bordo, y el buque, dejando el malecón, se alejó sobre un mar liso como una mesa de mármol verde."},{"fr":"Nous regardions les côtes s’enfuir, heureux et fiers comme tous ceux qui voyagent peu.","en":"We watched the coast slip away, happy and proud like all people who seldom travel.","pt":"Víamos a costa fugir, felizes e orgulhosos como todos os que viajam pouco.","es":"Mirábamos alejarse la costa, felices y orgullosos como todos los que viajan poco."}]},{"poem":false,"s":[{"fr":"Mon père tendait son ventre, sous sa redingote dont on avait, le matin même, effacé avec soin toutes les taches, et il répandait autour de lui cette odeur de benzine des jours de sortie, qui me faisait reconnaître les dimanches.","en":"My father thrust out his stomach under his frock coat, from which every stain had been carefully removed that very morning, and spread around him that smell of benzine of outing days that told me it was Sunday.","pt":"O meu pai deitava a barriga para a frente, debaixo da sobrecasaca, de que nessa mesma manhã se tinham tirado com cuidado todas as nódoas, e espalhava à sua volta aquele cheiro a benzina dos dias de saída, que me fazia reconhecer os domingos.","es":"Mi padre sacaba barriga bajo su levita, a la que esa misma mañana le habían quitado con cuidado todas las manchas, y esparcía a su alrededor aquel olor a bencina de los días de salida que me hacía reconocer los domingos."}]},{"poem":false,"s":[{"fr":"Tout à coup, il avisa deux dames élégantes à qui deux messieurs offraient des huîtres.","en":"Suddenly he noticed two elegant ladies to whom two gentlemen were offering oysters.","pt":"De repente, reparou em duas senhoras elegantes a quem dois senhores ofereciam ostras.","es":"De pronto vio a dos señoras elegantes a las que dos caballeros invitaban a ostras."},{"fr":"Un vieux matelot déguenillé ouvrait d’un coup de couteau les coquilles et les passait aux messieurs qui les tendaient ensuite aux dames.","en":"A ragged old sailor was opening the shells with a stroke of his knife and passing them to the gentlemen, who then handed them to the ladies.","pt":"Um velho marinheiro andrajoso abria as conchas com um golpe de faca e passava-as aos senhores, que depois as estendiam às senhoras.","es":"Un viejo marinero andrajoso abría las conchas de una cuchillada y se las pasaba a los caballeros, que luego se las ofrecían a las señoras."},{"fr":"Elles mangeaient d’une manière délicate, en tenant l’écaille sur un mouchoir fin et en avançant la bouche pour ne point tacher leurs robes.","en":"They ate them daintily, holding the shell on a fine handkerchief and pushing their mouths forward so as not to stain their dresses.","pt":"Elas comiam com delicadeza, segurando a concha sobre um lenço fino e avançando a boca para não mancharem os vestidos.","es":"Ellas comían de una manera delicada, sujetando la concha sobre un pañuelo fino y adelantando la boca para no mancharse los vestidos."},{"fr":"Puis elles buvaient l’eau d’un petit mouvement rapide et jetaient la coquille à la mer.","en":"Then they drank the juice with a quick little movement and threw the shell into the sea.","pt":"Depois bebiam a água com um movimento rápido e atiravam a concha ao mar.","es":"Luego se bebían el agua con un pequeño movimiento rápido y tiraban la concha al mar."}]},{"poem":false,"s":[{"fr":"Mon père, sans doute, fut séduit par cet acte distingué de manger des huîtres sur un navire en marche.","en":"My father was no doubt charmed by this distinguished act of eating oysters on a moving ship.","pt":"O meu pai foi decerto seduzido por aquele ato distinto de comer ostras num navio em andamento.","es":"A mi padre, sin duda, lo sedujo aquel acto distinguido de comer ostras en un barco en marcha."},{"fr":"Il trouva cela bon genre, raffiné, supérieur, et il s’approcha de ma mère et de mes sœurs en demandant :","en":"He thought it stylish, refined, superior, and he went up to my mother and my sisters and asked:","pt":"Achou aquilo de bom-tom, requintado, superior, e aproximou-se da minha mãe e das minhas irmãs, perguntando:","es":"Le pareció de buen tono, refinado, superior, y se acercó a mi madre y a mis hermanas preguntando:"}]},{"poem":false,"s":[{"fr":"— Voulez-vous que je vous offre quelques huîtres ?","en":"'Would you like me to buy you some oysters?'","pt":"«Querem que vos ofereça umas ostras?»","es":"—¿Queréis que os invite a unas ostras?"}]},{"poem":false,"s":[{"fr":"Ma mère hésitait, à cause de la dépense ; mais mes deux sœurs acceptèrent tout de suite.","en":"My mother hesitated because of the expense; but my two sisters accepted at once.","pt":"A minha mãe hesitava, por causa da despesa; mas as minhas duas irmãs aceitaram logo.","es":"Mi madre vacilaba, por el gasto; pero mis dos hermanas aceptaron enseguida."},{"fr":"Ma mère dit, d’un ton contrarié :","en":"My mother said, in an annoyed tone:","pt":"A minha mãe disse, em tom contrariado:","es":"Mi madre dijo, en tono contrariado:"}]},{"poem":false,"s":[{"fr":"— J’ai peur de me faire mal à l’estomac.","en":"'I'm afraid it will upset my stomach.","pt":"«Tenho medo de ficar mal do estômago.","es":"—Tengo miedo de que me sienten mal al estómago."},{"fr":"Offre ça aux enfants seulement, mais pas trop, tu les rendrais malades.","en":"Just get some for the children, but not too many, or you'll make them ill.'","pt":"Oferece só às miúdas, mas não muitas, que as pões doentes.»","es":"Invita solo a las chicas, pero no muchas, que las vas a poner enfermas."}]},{"poem":false,"s":[{"fr":"Puis, se tournant vers moi, elle ajouta :","en":"Then, turning to me, she added:","pt":"Depois, virando-se para mim, acrescentou:","es":"Luego, volviéndose hacia mí, añadió:"}]},{"poem":false,"s":[{"fr":"— Quant à Joseph, il n’en a pas besoin ; il ne faut point gâter les garçons.","en":"'As for Joseph, he doesn't need any; boys mustn't be spoiled.'","pt":"«Quanto ao Joseph, não precisa; não se deve estragar os rapazes com mimos.»","es":"—En cuanto a Joseph, no le hacen falta; no hay que mimar a los chicos."}]},{"poem":false,"s":[{"fr":"Je restai donc à côté de ma mère, trouvant injuste cette distinction.","en":"So I stayed beside my mother, finding the distinction unfair.","pt":"Fiquei então ao lado da minha mãe, achando injusta aquela distinção.","es":"Así que me quedé junto a mi madre, encontrando injusta aquella distinción."},{"fr":"Je suivais de l’œil mon père, qui conduisait pompeusement ses deux filles et son gendre vers le vieux matelot déguenillé.","en":"I followed my father with my eyes as he pompously led his two daughters and his son-in-law towards the ragged old sailor.","pt":"Seguia com os olhos o meu pai, que conduzia pomposamente as duas filhas e o genro para junto do velho marinheiro andrajoso.","es":"Seguía con la mirada a mi padre, que llevaba pomposamente a sus dos hijas y a su yerno hacia el viejo marinero andrajoso."}]},{"poem":false,"s":[{"fr":"Les deux dames venaient de partir, et mon père indiquait à mes sœurs comment il fallait s’y prendre pour manger sans laisser couler l’eau ; il voulut même donner l’exemple et il s’empara d’une huître.","en":"The two ladies had just left, and my father was showing my sisters how to go about it so as to eat without spilling the juice; he even wanted to set an example and grabbed an oyster.","pt":"As duas senhoras tinham acabado de se ir embora, e o meu pai mostrava às minhas irmãs como se devia fazer para comer sem deixar escorrer a água; quis até dar o exemplo e pegou numa ostra.","es":"Las dos señoras acababan de irse, y mi padre les enseñaba a mis hermanas cómo había que hacer para comer sin que se derramara el agua; hasta quiso dar ejemplo y cogió una ostra."},{"fr":"En essayant d’imiter les dames, il renversa immédiatement tout le liquide sur sa redingote et j’entendis ma mère murmurer :","en":"Trying to imitate the ladies, he immediately spilled all the liquid down his frock coat, and I heard my mother mutter:","pt":"Ao tentar imitar as senhoras, entornou logo todo o líquido na sobrecasaca, e ouvi a minha mãe murmurar:","es":"Al intentar imitar a las señoras, se derramó inmediatamente todo el líquido sobre la levita, y oí a mi madre murmurar:"}]},{"poem":false,"s":[{"fr":"— Il ferait mieux de se tenir tranquille.","en":"'He'd do better to keep still.'","pt":"«Fazia melhor em estar quieto.»","es":"—Mejor haría estándose quieto."}]},{"poem":false,"s":[{"fr":"Mais tout à coup mon père me parut inquiet ; il s’éloigna de quelques pas, regarda fixement sa famille pressée autour de l’écailleur, et, brusquement, il vint vers nous.","en":"But suddenly my father seemed uneasy to me; he moved a few steps away, stared at his family crowded around the oyster man, and abruptly came over to us.","pt":"Mas, de repente, o meu pai pareceu-me inquieto; afastou-se alguns passos, olhou fixamente para a família apertada à volta do vendedor de ostras e, bruscamente, veio ter connosco.","es":"Pero de repente mi padre me pareció inquieto; se alejó unos pasos, miró fijamente a su familia apiñada alrededor del vendedor de ostras y, bruscamente, vino hacia nosotros."},{"fr":"Il me sembla fort pâle, avec des yeux singuliers.","en":"He looked very pale to me, with a strange look in his eyes.","pt":"Pareceu-me muito pálido, com uns olhos estranhos.","es":"Me pareció muy pálido, con unos ojos extraños."},{"fr":"Il dit, à mi-voix, à ma mère :","en":"He said to my mother in a low voice:","pt":"Disse à minha mãe, a meia-voz:","es":"Le dijo a mi madre a media voz:"}]},{"poem":false,"s":[{"fr":"— C’est extraordinaire, comme cet homme qui ouvre les huîtres ressemble à Jules.","en":"'It's extraordinary how much that man opening the oysters looks like Jules.'","pt":"«É extraordinário como aquele homem que abre as ostras se parece com o Jules.»","es":"—Es extraordinario lo que se parece a Jules ese hombre que abre las ostras."}]},{"poem":false,"s":[{"fr":"Ma mère, interdite, demanda :","en":"My mother, taken aback, asked:","pt":"A minha mãe, interdita, perguntou:","es":"Mi madre, desconcertada, preguntó:"}]},{"poem":false,"s":[{"fr":"— Quel Jules ?…","en":"'Which Jules?…'","pt":"«Que Jules?…»","es":"—¿Qué Jules?…"}]},{"poem":false,"s":[{"fr":"Mon père reprit :","en":"My father went on:","pt":"O meu pai continuou:","es":"Mi padre continuó:"}]},{"poem":false,"s":[{"fr":"— Mais… mon frère…","en":"'Why… my brother…","pt":"«Mas… o meu irmão…","es":"—Pues… mi hermano…"},{"fr":"Si je ne le savais pas en bonne position en Amérique, je croirais que c’est lui.","en":"If I didn't know he was doing well in America, I'd think it was him.'","pt":"Se não soubesse que está bem instalado na América, julgava que era ele.»","es":"Si no supiera que está en buena posición en América, creería que es él."}]},{"poem":false,"s":[{"fr":"Ma mère effarée balbutia :","en":"My mother, alarmed, stammered:","pt":"A minha mãe, assustada, balbuciou:","es":"Mi madre, espantada, balbuceó:"}]},{"poem":false,"s":[{"fr":"— Tu es fou !","en":"'You're mad!","pt":"«Estás doido!","es":"—¡Estás loco!"},{"fr":"Du moment que tu sais bien que ce n’est pas lui, pourquoi dire ces bêtises-là ?","en":"Since you know perfectly well it isn't him, why say such silly things?'","pt":"Se sabes bem que não é ele, porque dizes essas asneiras?»","es":"Si sabes muy bien que no es él, ¿por qué dices esas tonterías?"}]},{"poem":false,"s":[{"fr":"— Va donc le voir, Clarisse ; j’aime mieux que tu t’en assures toi-même, de tes propres yeux.","en":"'Go and look at him, Clarisse; I'd rather you made sure for yourself, with your own eyes.'","pt":"«Vai lá vê-lo, Clarisse; prefiro que te certifiques tu mesma, com os teus próprios olhos.»","es":"—Ve a verlo, Clarisse; prefiero que te asegures tú misma, con tus propios ojos."}]},{"poem":false,"s":[{"fr":"Elle se leva et alla rejoindre ses filles.","en":"She got up and went to join her daughters.","pt":"Ela levantou-se e foi ter com as filhas.","es":"Ella se levantó y fue a reunirse con sus hijas."},{"fr":"Moi aussi, je regardais l’homme.","en":"I was looking at the man too.","pt":"Eu também olhava para o homem.","es":"Yo también miraba al hombre."},{"fr":"Il était vieux, sale, tout ridé, et ne détournait pas le regard de sa besogne.","en":"He was old, dirty, all wrinkled, and didn't take his eyes off his work.","pt":"Era velho, sujo, todo enrugado, e não tirava os olhos do trabalho.","es":"Era viejo, sucio, todo arrugado, y no apartaba la vista de su trabajo."}]},{"poem":false,"s":[{"fr":"Ma mère revint.","en":"My mother came back.","pt":"A minha mãe voltou.","es":"Mi madre volvió."},{"fr":"Je m’aperçus qu’elle tremblait.","en":"I noticed she was trembling.","pt":"Reparei que tremia.","es":"Me di cuenta de que temblaba."},{"fr":"Elle prononça très vite :","en":"She said very quickly:","pt":"Disse muito depressa:","es":"Dijo muy deprisa:"}]},{"poem":false,"s":[{"fr":"— Je crois que c’est lui.","en":"'I think it is him.","pt":"«Acho que é ele.","es":"—Creo que es él."},{"fr":"Va donc demander des renseignements au capitaine.","en":"Go and ask the captain about him.","pt":"Vai pedir informações ao capitão.","es":"Ve a pedirle información al capitán."},{"fr":"Surtout sois prudent, pour que ce garnement ne nous retombe pas sur les bras, maintenant !","en":"And above all be careful, so that the good-for-nothing doesn't land back on our hands now!'","pt":"E sobretudo tem cuidado, para que esse malandro não nos caia outra vez em cima, agora!»","es":"Sobre todo ten cuidado, ¡que no se nos eche encima ahora ese granuja!"}]},{"poem":false,"s":[{"fr":"Mon père s’éloigna, mais je le suivis.","en":"My father moved off, but I followed him.","pt":"O meu pai afastou-se, mas eu segui-o.","es":"Mi padre se alejó, pero yo lo seguí."},{"fr":"Je me sentais étrangement ému.","en":"I felt strangely moved.","pt":"Sentia-me estranhamente comovido.","es":"Me sentía extrañamente conmovido."}]},{"poem":false,"s":[{"fr":"Le capitaine, un grand monsieur, maigre, à longs favoris, se promenait sur la passerelle d’un air important, comme s’il eût commandé le courrier des Indes.","en":"The captain, a tall, thin gentleman with long side-whiskers, was pacing the bridge with an important air, as if he were in command of the mail ship to India.","pt":"O capitão, um senhor alto e magro, de suíças compridas, passeava pela ponte com ar importante, como se comandasse o correio das Índias.","es":"El capitán, un señor alto, flaco, de largas patillas, se paseaba por el puente con aire importante, como si mandara el correo de las Indias."}]},{"poem":false,"s":[{"fr":"Mon père l’aborda avec cérémonie, en l’interrogeant sur son métier avec accompagnement de compliments :","en":"My father approached him ceremoniously, asking him about his work with a string of compliments:","pt":"O meu pai abordou-o com cerimónia, interrogando-o sobre o seu ofício, com acompanhamento de cumprimentos:","es":"Mi padre lo abordó con ceremonia, interrogándolo sobre su oficio acompañado de cumplidos:"}]},{"poem":false,"s":[{"fr":"— Quelle était l’importance de Jersey ?","en":"What was the importance of Jersey?","pt":"Qual era a importância de Jersey?","es":"¿Qué importancia tenía Jersey?"},{"fr":"Ses productions ?","en":"Its products?","pt":"As suas produções?","es":"¿Sus productos?"},{"fr":"Sa population ?","en":"Its population?","pt":"A sua população?","es":"¿Su población?"},{"fr":"Ses mœurs ?","en":"Its manners?","pt":"Os seus costumes?","es":"¿Sus costumbres?"},{"fr":"Ses coutumes ?","en":"Its customs?","pt":"As suas tradições?","es":"¿Sus usos?"},{"fr":"La nature du sol, etc., etc.","en":"The nature of its soil, and so on and so forth.","pt":"A natureza do solo, etc., etc.","es":"¿La naturaleza del suelo?, etcétera, etcétera."}]},{"poem":false,"s":[{"fr":"On eût cru qu’il s’agissait au moins des États-Unis d’Amérique.","en":"You would have thought they were talking about the United States of America at the very least.","pt":"Parecia que se tratava pelo menos dos Estados Unidos da América.","es":"Se habría dicho que se trataba por lo menos de los Estados Unidos de América."}]},{"poem":false,"s":[{"fr":"Puis on parla du bâtiment qui nous portait, l’Express, puis on en vint à l’équipage.","en":"Then they talked about the ship we were on, the Express, and then they came to the crew.","pt":"Depois falou-se do barco que nos levava, o Express, e depois chegou-se à tripulação.","es":"Luego se habló del barco que nos llevaba, el Express, y después se pasó a la tripulación."},{"fr":"Mon père, enfin, d’une voix troublée :","en":"At last my father said, in an unsteady voice:","pt":"Por fim, o meu pai disse, com voz perturbada:","es":"Mi padre, por fin, con voz turbada:"}]},{"poem":false,"s":[{"fr":"— Vous avez là un vieil écailleur d’huîtres qui parait bien intéressant.","en":"'You have an old oyster-opener there who seems very interesting.","pt":"«Tem ali um velho que abre ostras que parece muito interessante.","es":"—Tiene usted ahí a un viejo vendedor de ostras que parece muy interesante."},{"fr":"Savez-vous quelques détails sur ce bonhomme ?","en":"Do you know anything about the old fellow?'","pt":"Sabe alguns pormenores sobre esse velhote?»","es":"¿Sabe algo de ese buen hombre?"}]},{"poem":false,"s":[{"fr":"Le capitaine, que cette conversation finissait par irriter, répondit sèchement :","en":"The captain, who was beginning to find this conversation irritating, answered curtly:","pt":"O capitão, que aquela conversa acabava por irritar, respondeu secamente:","es":"El capitán, al que aquella conversación acababa por irritar, respondió secamente:"}]},{"poem":false,"s":[{"fr":"— C’est un vieux vagabond français que j’ai trouvé en Amérique l’an dernier, et que j’ai rapatrié.","en":"'He's an old French tramp I found in America last year and brought back home.","pt":"«É um velho vagabundo francês que encontrei na América no ano passado e que repatriei.","es":"—Es un viejo vagabundo francés que encontré en América el año pasado y que repatrié."},{"fr":"Il a, paraît-il, des parents au Havre, mais il ne veut pas retourner près d’eux, parce qu’il leur doit de l’argent.","en":"It seems he has relatives in Le Havre, but he doesn't want to go back to them because he owes them money.","pt":"Parece que tem família no Havre, mas não quer voltar para junto dela, porque lhe deve dinheiro.","es":"Al parecer tiene parientes en El Havre, pero no quiere volver con ellos porque les debe dinero."},{"fr":"Il s’appelle Jules…","en":"His name is Jules…","pt":"Chama-se Jules…","es":"Se llama Jules…"},{"fr":"Jules Darmanche ou Darvanche, quelque chose comme ça, enfin.","en":"Jules Darmanche or Darvanche, something like that.","pt":"Jules Darmanche ou Darvanche, qualquer coisa assim.","es":"Jules Darmanche o Darvanche, algo así."},{"fr":"Il paraît qu’il a été riche un moment là-bas, mais vous voyez où il en est réduit maintenant.","en":"It seems he was rich for a while over there, but you can see what he's come down to now.'","pt":"Parece que foi rico durante algum tempo lá, mas vê a que está reduzido agora.»","es":"Parece que fue rico allí durante un tiempo, pero ya ve a qué ha quedado reducido ahora."}]},{"poem":false,"s":[{"fr":"Mon père, qui devenait livide, articula, la gorge serrée, les yeux hagards :","en":"My father, who was turning ashen, got the words out, his throat tight and his eyes wild:","pt":"O meu pai, que ficava lívido, articulou, de garganta apertada e olhos esgazeados:","es":"Mi padre, que se estaba poniendo lívido, articuló con la garganta encogida y los ojos extraviados:"}]},{"poem":false,"s":[{"fr":"— Ah ! ah ! très bien… fort bien…","en":"'Ah! Ah! Very good… very good indeed…","pt":"«Ah! Ah! Muito bem… muitíssimo bem…","es":"—¡Ah, ah! Muy bien… perfectamente…"},{"fr":"Cela ne m’étonne pas…","en":"That doesn't surprise me…","pt":"Não me admira…","es":"No me extraña…"},{"fr":"Je vous remercie beaucoup, capitaine.","en":"Thank you very much, captain.'","pt":"Muito obrigado, capitão.»","es":"Muchas gracias, capitán."}]},{"poem":false,"s":[{"fr":"Et il s’en alla, tandis que le marin le regardait s’éloigner avec stupeur.","en":"And he went off, while the sailor watched him go in astonishment.","pt":"E foi-se embora, enquanto o marinheiro o via afastar-se, estupefacto.","es":"Y se fue, mientras el marino lo miraba alejarse con estupor."}]},{"poem":false,"s":[{"fr":"Il revint auprès de ma mère, tellement décomposé qu’elle lui dit :","en":"He came back to my mother looking so shattered that she said to him:","pt":"Voltou para junto da minha mãe, tão transtornado que ela lhe disse:","es":"Volvió junto a mi madre, tan descompuesto que ella le dijo:"}]},{"poem":false,"s":[{"fr":"— Assieds-toi ; on va s’apercevoir de quelque chose.","en":"'Sit down; people will notice something.'","pt":"«Senta-te; vão dar por alguma coisa.»","es":"—Siéntate; se van a dar cuenta de algo."}]},{"poem":false,"s":[{"fr":"Il tomba sur le banc en bégayant :","en":"He dropped onto the bench, stammering:","pt":"Ele deixou-se cair no banco, a gaguejar:","es":"Se dejó caer en el banco, tartamudeando:"}]},{"poem":false,"s":[{"fr":"— C’est lui, c’est bien lui !","en":"'It's him, it really is him!'","pt":"«É ele, é mesmo ele!»","es":"—¡Es él, es él de verdad!"}]},{"poem":false,"s":[{"fr":"Puis il demanda.","en":"Then he asked:","pt":"Depois perguntou:","es":"Luego preguntó:"}]},{"poem":false,"s":[{"fr":"— Qu’allons-nous faire ?…","en":"'What are we going to do?…'","pt":"«Que vamos fazer?…»","es":"—¿Qué vamos a hacer?…"}]},{"poem":false,"s":[{"fr":"Elle répondit vivement.","en":"She answered sharply:","pt":"Ela respondeu prontamente:","es":"Ella respondió con viveza:"}]},{"poem":false,"s":[{"fr":"— Il faut éloigner les enfants.","en":"'We must get the children away.","pt":"«Temos de afastar as filhas.","es":"—Hay que alejar a los chicos."},{"fr":"Puisque Joseph sait tout, il va aller les chercher.","en":"Since Joseph knows everything, he'll go and fetch them.","pt":"Já que o Joseph sabe tudo, vai ele buscá-las.","es":"Ya que Joseph lo sabe todo, que vaya a buscarlos."},{"fr":"Il faut prendre garde surtout que notre gendre ne se doute de rien.","en":"Above all we must make sure our son-in-law doesn't suspect anything.'","pt":"Temos sobretudo de ter cuidado para que o nosso genro não desconfie de nada.»","es":"Sobre todo hay que tener cuidado de que nuestro yerno no sospeche nada."}]},{"poem":false,"s":[{"fr":"Mon père paraissait atterré.","en":"My father seemed crushed.","pt":"O meu pai parecia aterrado.","es":"Mi padre parecía abatido."},{"fr":"Il murmura :","en":"He murmured:","pt":"Murmurou:","es":"Murmuró:"}]},{"poem":false,"s":[{"fr":"— Quelle catastrophe !","en":"'What a disaster!'","pt":"«Que catástrofe!»","es":"—¡Qué catástrofe!"}]},{"poem":false,"s":[{"fr":"Ma mère ajouta, devenue tout à coup furieuse :","en":"My mother added, suddenly furious:","pt":"A minha mãe acrescentou, de repente furiosa:","es":"Mi madre añadió, de repente furiosa:"}]},{"poem":false,"s":[{"fr":"— Je me suis toujours doutée que ce voleur ne ferait rien, et qu’il nous retomberait sur le dos !","en":"'I always suspected that thief would never come to anything, and that he'd land back on our backs!","pt":"«Sempre desconfiei que esse ladrão não havia de fazer nada e que nos havia de cair outra vez em cima!","es":"—¡Siempre sospeché que ese ladrón no haría nada de provecho y que acabaría cayéndonos encima!"},{"fr":"Comme si on pouvait attendre quelque chose d’un Davranche !…","en":"As if you could expect anything from a Davranche!…'","pt":"Como se se pudesse esperar alguma coisa de um Davranche!…»","es":"¡Como si se pudiera esperar algo de un Davranche!…"}]},{"poem":false,"s":[{"fr":"Et mon père se passa la main sur le front, comme il faisait sous les reproches de sa femme.","en":"And my father passed his hand across his forehead, as he did when his wife reproached him.","pt":"E o meu pai passou a mão pela testa, como fazia quando a mulher o censurava.","es":"Y mi padre se pasó la mano por la frente, como hacía ante los reproches de su mujer."}]},{"poem":false,"s":[{"fr":"Elle ajouta :","en":"She added:","pt":"Ela acrescentou:","es":"Ella añadió:"}]},{"poem":false,"s":[{"fr":"— Donne de l’argent à Joseph pour qu’il aille payer ces huîtres, à présent.","en":"'Give Joseph some money so he can go and pay for those oysters now.","pt":"«Dá dinheiro ao Joseph para ele ir pagar as ostras, agora.","es":"—Dale dinero a Joseph para que vaya a pagar esas ostras, ahora."},{"fr":"Il ne manquerait plus que d’être reconnu par ce mendiant.","en":"All we need is to be recognised by that beggar.","pt":"Só faltava sermos reconhecidos por esse mendigo.","es":"Solo faltaría que nos reconociera ese mendigo."},{"fr":"Cela ferait un joli effet sur le navire.","en":"That would look lovely on the ship.","pt":"Era um lindo espetáculo no navio.","es":"¡Qué bonito efecto haría en el barco!"},{"fr":"Allons-nous-en à l’autre bout, et fais en sorte que cet homme n’approche pas de nous !","en":"Let's go to the other end, and make sure that man doesn't come near us!'","pt":"Vamos para a outra ponta, e faz com que esse homem não se aproxime de nós!»","es":"Vámonos al otro extremo, ¡y procura que ese hombre no se nos acerque!"}]},{"poem":false,"s":[{"fr":"Elle se leva, et ils s’éloignèrent après m’avoir remis une pièce de cent sous.","en":"She stood up, and they moved away after handing me a five-franc coin.","pt":"Levantou-se, e afastaram-se depois de me darem uma moeda de cinco francos.","es":"Se levantó, y se alejaron después de darme una moneda de cinco francos."}]},{"poem":false,"s":[{"fr":"Mes sœurs, surprises, attendaient leur père.","en":"My sisters were surprised and waiting for their father.","pt":"As minhas irmãs, surpreendidas, esperavam pelo pai.","es":"Mis hermanas, sorprendidas, esperaban a su padre."},{"fr":"J’affirmai que maman s’était trouvée un peu gênée par la mer, et je demandai à l’ouvreur d’huîtres :","en":"I said that Mama had been feeling a little seasick, and I asked the oyster-opener:","pt":"Disse que a mamã se tinha sentido um pouco enjoada com o mar, e perguntei ao homem das ostras:","es":"Les aseguré que mamá se había mareado un poco con el mar, y le pregunté al que abría las ostras:"}]},{"poem":false,"s":[{"fr":"— Combien est-ce que nous vous devons, monsieur ?","en":"'How much do we owe you, sir?'","pt":"«Quanto lhe devemos, senhor?»","es":"—¿Cuánto le debemos, señor?"}]},{"poem":false,"s":[{"fr":"J’avais envie de dire : mon oncle.","en":"I wanted to say: Uncle.","pt":"Tinha vontade de dizer: meu tio.","es":"Tenía ganas de decirle: tío."}]},{"poem":false,"s":[{"fr":"Il répondit :","en":"He answered:","pt":"Ele respondeu:","es":"Respondió:"}]},{"poem":false,"s":[{"fr":"— Deux francs cinquante.","en":"'Two francs fifty.'","pt":"«Dois francos e cinquenta.»","es":"—Dos francos cincuenta."}]},{"poem":false,"s":[{"fr":"Je tendis mes cent sous et il me rendit la monnaie.","en":"I held out my five francs and he gave me the change.","pt":"Estendi os meus cinco francos e ele deu-me o troco.","es":"Le di mis cinco francos y me devolvió el cambio."}]},{"poem":false,"s":[{"fr":"Je regardais sa main, une pauvre main de matelot toute plissée, et je regardais son visage, un vieux misérable visage, triste, accablé, en me disant :","en":"I looked at his hand, a poor sailor's hand all creased, and I looked at his face, an old, wretched face, sad and beaten down, and I said to myself:","pt":"Olhava para a mão dele, uma pobre mão de marinheiro toda engelhada, e olhava para a cara dele, uma cara velha e miserável, triste, abatida, dizendo para mim:","es":"Le miraba la mano, una pobre mano de marinero toda arrugada, y le miraba la cara, una vieja cara miserable, triste, abatida, diciéndome:"}]},{"poem":false,"s":[{"fr":"C’est mon oncle, le frère de papa, mon oncle !","en":"That's my uncle, Papa's brother, my uncle!","pt":"É o meu tio, o irmão do papá, o meu tio!","es":"¡Es mi tío, el hermano de papá, mi tío!"}]},{"poem":false,"s":[{"fr":"Je lui laissai dix sous de pourboire.","en":"I left him a tip of ten sous.","pt":"Deixei-lhe dez tostões de gorjeta.","es":"Le dejé cincuenta céntimos de propina."},{"fr":"Il me remercia :","en":"He thanked me:","pt":"Ele agradeceu-me:","es":"Me dio las gracias:"}]},{"poem":false,"s":[{"fr":"— Dieu vous bénisse, mon jeune monsieur !","en":"'God bless you, young sir!'","pt":"«Deus o abençoe, meu jovem senhor!»","es":"—¡Dios se lo pague, señorito!"}]},{"poem":false,"s":[{"fr":"Avec l’accent d’un pauvre qui reçoit l’aumône.","en":"In the voice of a poor man receiving charity.","pt":"Com a entoação de um pobre que recebe esmola.","es":"Con el acento de un pobre que recibe una limosna."},{"fr":"Je pensai qu’il avait dû mendier, là-bas !","en":"I thought he must have begged over there!","pt":"Pensei que ele devia ter pedido esmola, lá longe!","es":"¡Pensé que allí debía de haber pedido limosna!"}]},{"poem":false,"s":[{"fr":"Mes sœurs me contemplaient, stupéfaites de ma générosité.","en":"My sisters stared at me, amazed at my generosity.","pt":"As minhas irmãs olhavam para mim, estupefactas com a minha generosidade.","es":"Mis hermanas me miraban, estupefactas de mi generosidad."}]},{"poem":false,"s":[{"fr":"Quand je remis les deux francs à mon père, ma mère, surprise, demanda :","en":"When I gave the two francs back to my father, my mother asked in surprise:","pt":"Quando entreguei os dois francos ao meu pai, a minha mãe, surpreendida, perguntou:","es":"Cuando le devolví los dos francos a mi padre, mi madre, sorprendida, preguntó:"}]},{"poem":false,"s":[{"fr":"— Il y en avait pour trois francs ?…","en":"'It came to three francs?…","pt":"«Foram três francos?…","es":"—¿Costaban tres francos?…"},{"fr":"Ce n’est pas possible.","en":"That's not possible.'","pt":"Não é possível.»","es":"No es posible."}]},{"poem":false,"s":[{"fr":"— J’ai donné dix sous de pourboire.","en":"'I gave a ten-sou tip.'","pt":"«Dei dez tostões de gorjeta.»","es":"—He dado cincuenta céntimos de propina."}]},{"poem":false,"s":[{"fr":"Ma mère eut un sursaut et me regarda dans les yeux :","en":"My mother started and looked me in the eyes:","pt":"A minha mãe teve um sobressalto e olhou-me nos olhos:","es":"Mi madre dio un respingo y me miró a los ojos:"}]},{"poem":false,"s":[{"fr":"— Tu es fou !","en":"'You're mad!","pt":"«Estás doido!","es":"—¡Estás loco!"},{"fr":"Donner dix sous à cet homme, à ce gueux !…","en":"Giving ten sous to that man, that wretch!…'","pt":"Dar dez tostões àquele homem, àquele pelintra!…»","es":"¡Darle cincuenta céntimos a ese hombre, a ese miserable!…"}]},{"poem":false,"s":[{"fr":"Elle s’arrêta sous un regard de mon père, qui désignait son gendre.","en":"She stopped at a look from my father, who nodded towards his son-in-law.","pt":"Calou-se diante de um olhar do meu pai, que lhe indicava o genro.","es":"Se calló ante una mirada de mi padre, que señalaba a su yerno."}]},{"poem":false,"s":[{"fr":"Puis on se tut.","en":"Then nobody said anything.","pt":"Depois ninguém disse mais nada.","es":"Luego nos quedamos en silencio."}]},{"poem":false,"s":[{"fr":"Devant nous, à l’horizon, une ombre violette semblait sortir de la mer.","en":"Ahead of us, on the horizon, a purple shadow seemed to rise out of the sea.","pt":"À nossa frente, no horizonte, uma sombra violeta parecia sair do mar.","es":"Delante de nosotros, en el horizonte, una sombra violeta parecía salir del mar."},{"fr":"C’était Jersey.","en":"It was Jersey.","pt":"Era Jersey.","es":"Era Jersey."}]},{"poem":false,"s":[{"fr":"Lorsqu’on approcha des jetées, un désir violent me vint au cœur de voir encore une fois mon oncle Jules, de m’approcher, de lui dire quelque chose de consolant, de tendre.","en":"As we came near the piers, a fierce longing came into my heart to see my uncle Jules once more, to go up to him and say something comforting and tender to him.","pt":"Quando nos aproximámos dos molhes, veio-me ao coração um desejo violento de ver mais uma vez o meu tio Jules, de me aproximar, de lhe dizer alguma coisa de consolador, de terno.","es":"Cuando nos acercábamos a los malecones, me vino al corazón un deseo violento de ver otra vez a mi tío Jules, de acercarme y decirle algo consolador, algo tierno."}]},{"poem":false,"s":[{"fr":"Mais, comme personne ne mangeait plus d’huîtres, il avait disparu, descendu sans doute au fond de la cale infecte où logeait ce misérable.","en":"But since nobody was eating oysters any more, he had disappeared, no doubt gone down into the foul hold where the poor wretch lived.","pt":"Mas, como já ninguém comia ostras, ele tinha desaparecido, descido decerto ao fundo do porão infecto onde vivia aquele desgraçado.","es":"Pero, como ya nadie comía ostras, había desaparecido, bajado sin duda al fondo de la bodega infecta donde dormía aquel desgraciado."}]},{"poem":false,"s":[{"fr":"Et nous sommes revenus par le bateau de Saint-Malo, pour ne pas le rencontrer.","en":"And we came back on the Saint-Malo boat so as not to meet him.","pt":"E voltámos pelo barco de Saint-Malo, para não o encontrar.","es":"Y volvimos en el barco de Saint-Malo, para no encontrárnoslo."},{"fr":"Ma mère était dévorée d’inquiétude.","en":"My mother was eaten up with worry.","pt":"A minha mãe estava devorada pela inquietação.","es":"Mi madre estaba devorada por la inquietud."}]},{"poem":false,"s":[{"fr":"Je n’ai jamais revu le frère de mon père !","en":"I never saw my father's brother again!","pt":"Nunca mais voltei a ver o irmão do meu pai!","es":"¡Nunca volví a ver al hermano de mi padre!"}]},{"poem":false,"s":[{"fr":"Voilà pourquoi tu me verras quelquefois donner cent sous aux vagabonds.","en":"That's why you'll sometimes see me give five francs to tramps.\"","pt":"É por isso que me verás às vezes dar cinco francos aos vagabundos.","es":"Por eso me verás a veces dar cinco francos a los vagabundos."}]}]});
